"""Development supervisor: restart the demo server when Python source changes."""
import argparse
from pathlib import Path
import subprocess
import sys
import time
from urllib.error import URLError
from urllib.request import urlopen
import webbrowser


ROOT = Path(__file__).resolve().parents[2]
PYTHON_SOURCE = ROOT / "cores" / "python"


def snapshot():
    """Capture source file metadata, excluding generated bytecode directories."""
    result = {}
    for path in PYTHON_SOURCE.rglob("*.py"):
        if "__pycache__" in path.parts:
            continue
        try:
            stat = path.stat()
        except OSError:
            continue
        result[str(path)] = (stat.st_mtime_ns, stat.st_size)
    return result


def stop(process):
    if process.poll() is None:
        process.terminate()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()


def wait_ready(process, port, timeout=15):
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline and process.poll() is None:
        try:
            with urlopen(f"http://127.0.0.1:{port}/__dev/revision", timeout=.5) as response:
                return response.status == 200
        except (OSError, URLError):
            time.sleep(.1)
    return False


def main():
    parser = argparse.ArgumentParser(description="Dashboard development server with Python auto-restart")
    parser.add_argument("--port", type=int, default=8765, help="Stable local port for browser reloads (default: 8765)")
    parser.add_argument("--no-open", action="store_true", help="Do not open the browser")
    args = parser.parse_args()
    if not 1 <= args.port <= 65535:
        parser.error("port must be between 1 and 65535")

    url = f"http://127.0.0.1:{args.port}/"
    print(f"Development dashboard: {url}", flush=True)

    command = [sys.executable, "-u", str(PYTHON_SOURCE / "jira_demo.py"),
               "--hot-reload", "--no-open", "--port", str(args.port)]
    process = None
    observed = snapshot()
    browser_opened = args.no_open
    print("Watching cores/python/*.py; Python edits restart the server. Ctrl+C stops it.", flush=True)
    try:
        while True:
            if process is None or process.poll() is not None:
                process = subprocess.Popen(command, cwd=ROOT)
                if wait_ready(process, args.port):
                    if not browser_opened:
                        try:
                            webbrowser.open_new_tab(url)
                        except (OSError, webbrowser.Error):
                            pass
                        browser_opened = True
                elif process.poll() is None:
                    print("Dashboard did not become ready within 15 seconds.", flush=True)
            time.sleep(.4)
            current = snapshot()
            if current != observed:
                # Wait until an editor's write/rename has settled before importing source.
                time.sleep(.35)
                current = snapshot()
                if current != observed:
                    print("Python source changed; restarting dashboard...", flush=True)
                    stop(process)
                    process = None
                    observed = current
    except KeyboardInterrupt:
        print("Development server stopped.", flush=True)
    finally:
        if process is not None:
            stop(process)


if __name__ == "__main__":
    main()
